loki.write "default" {
  endpoint {
    url = "http://loki.observability.svc.cluster.local:3100/loki/api/v1/push"
  }
}

// ---------- TrueNAS: RFC 5424 over TCP ----------
loki.source.syslog "truenas" {
  listener {
    address                = "0.0.0.0:1515"
    protocol               = "tcp"
    syslog_format          = "rfc5424"
    idle_timeout           = "24h"
    use_incoming_timestamp = true
    labels = {
      job  = "truenas",
      host = "truenas",
    }
  }
  relabel_rules = loki.relabel.truenas.rules
  forward_to    = [loki.process.truenas.receiver]
}

loki.relabel "truenas" {
  rule {
    source_labels = ["__syslog_connection_ip_address"]
    regex         = "192\\.168\\.10\\.75"
    action        = "keep"
  }
  rule {
    target_label = "app"
    replacement  = "other"
  }
  rule {
    source_labels = ["__syslog_message_app_name"]
    regex         = "(MIDDLEWARE|APP_LIFECYCLE|ZETTAREPL|DOCKER_IMAGE|kernel|systemd|smartd|zed|syslog-ng|sshd|nginx|dockerd|containerd|cron|CRON|qemu-ga|nscd)"
    target_label  = "app"
    replacement   = "$1"
  }
  rule {
    source_labels = ["__syslog_message_severity"]
    target_label  = "level"
  }
  forward_to = []
}

// ---------- UniFi gateway: RFC 3164 over UDP ----------
loki.source.syslog "ucg" {
  listener {
    address        = "0.0.0.0:1514"
    protocol       = "udp"
    syslog_format  = "rfc3164"
    udp_queue_size = 1000
    labels = {
      job  = "ucg",
      host = "ucg",
    }
  }
  relabel_rules = loki.relabel.ucg.rules
  forward_to    = [loki.process.ucg.receiver]
}

loki.relabel "ucg" {
  rule {
    source_labels = ["__syslog_connection_ip_address"]
    regex         = "192\\.168\\.10\\.1|192\\.168\\.1\\.1"
    action        = "keep"
  }
  rule {
    target_label = "app"
    replacement  = "other"
  }
  rule {
    source_labels = ["__syslog_message_app_name"]
    regex         = "(kernel|systemd|sshd|dnsmasq|dhcpd|hostapd|ubios-udapi-server|ulogd|ips|suricata|unifi-core|ucore|mongod|cron|CRON)"
    target_label  = "app"
    replacement   = "$1"
  }
  rule {
    source_labels = ["__syslog_message_severity"]
    target_label  = "level"
  }
  forward_to = []
}

// ---------- size, redaction and rate cap, one pipeline per source ----------
// Separate limiters: a flood of forged UDP lines cannot use up TrueNAS's
// budget.
loki.process "truenas" {
  stage.match {
    // The source-address filter. A `keep` rule in the relabel step does NOT
    // drop the line (Alloy v1.21.1 stores it under the listener's fixed
    // labels); it only skips the relabel rules, so the line has no `app`
    // label. This stage drops every line without `app`.
    selector            = "{job=~\".+\", app=\"\"}"
    action              = "drop"
    drop_counter_reason = "source_not_allowed"
  }
  stage.drop {
    longer_than = "4KB"
  }
  // Webhook tokens. Only the capture group (the token) is replaced.
  // Discord: /api/webhooks/<id>/<token>, with or without /v<N>/, any
  // host. Slack: hooks.slack.com/services/<team>/<bot>/<token>.
  // "/" or URL-encoded "%2F" between the parts.
  stage.replace {
    expression = "(?:/|%2[Ff])api(?:/|%2[Ff])(?:v[0-9]+(?:/|%2[Ff]))?webhooks(?:/|%2[Ff])[0-9]+(?:/|%2[Ff])([A-Za-z0-9_-]+)"
    replace    = "<redacted>"
  }
  stage.replace {
    expression = "hooks\\.slack\\.com(?:/|%2[Ff])services(?:/|%2[Ff])[A-Za-z0-9_-]+(?:/|%2[Ff])[A-Za-z0-9_-]+(?:/|%2[Ff])([A-Za-z0-9_-]+)"
    replace    = "<redacted>"
  }
  stage.limit {
    rate  = 5
    burst = 100
    drop  = true
  }
  forward_to = [loki.write.default.receiver]
}

loki.process "ucg" {
  stage.match {
    // The source-address filter. A `keep` rule in the relabel step does NOT
